with a as(select * from public.authors where open_library_id=any(array['OL2660296A','OL10419220A','OL8328825A','OL14415775A','OL14415747A','OL185745A','OL22258A','OL8102042A','OL7809945A','OL7644400A']::text[]) or id=any(array[884,3168,342]::bigint[])) select jsonb_build_object('checked_at',clock_timestamp(),'authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'isbn_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9789060195529','9789038807416','9789022594735']::text[])),'source_work_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where open_library_id=any(array['OL962240W','OL21254611W','OL24211941W']::text[])),'title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','works','row',to_jsonb(t))),'[]') from public.works t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['justine','justineofdetegenspoedderdeugdzaamheid','dobakoze','hettijdperkvandehuid','thenoise','oorverdovend']::text[])),'edition_title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','editions','row',to_jsonb(t))),'[]') from public.editions t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['justine','justineofdetegenspoedderdeugdzaamheid','dobakoze','hettijdperkvandehuid','thenoise','oorverdovend']::text[])),'reserved_test_ranges',jsonb_build_object('works',(select count(*) from public.works where id between 987132001 and 987132999),'editions',(select count(*) from public.editions where id between 987232001 and 987232999),'authors',(select count(*) from public.authors where id between 987332001 and 987332999))) as preflight;
